INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14901, 'Psalms 118:20', 'Psalms', 118, 20, '&nbsp;دا د مالِک خُدائ دروازه ده، په کومه به چې صادقان ورداخل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14902, 'Psalms 118:21', 'Psalms', 118, 21, '&nbsp;زۀ به ستا شُکر ادا کړم، ځکه چې تا ما ته جواب راکړے دے، تۀ زما خلاصونکے جوړ شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14903, 'Psalms 118:22', 'Psalms', 118, 22, '&nbsp;کوم کاڼے چې ګِلکارانو رد کړے دے، هم هغه کاڼے د ګوټ سر کاڼے جوړ شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14904, 'Psalms 118:23', 'Psalms', 118, 23, '&nbsp;دا کارونه مالِک خُدائ کړى دى، دا زمونږ په خيال حېرانوونکے منظر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14905, 'Psalms 118:24', 'Psalms', 118, 24, '&nbsp;دا هغه ورځ ده چې مالِک خُدائ جوړه کړې ده، نو راځئ چې خوشحالى وکړُو، او په کښې خوشحاله اوسو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14906, 'Psalms 118:25', 'Psalms', 118, 25, '&nbsp;اے مالِکه خُدايه مونږه بچ کړه، اے مالِکه خُدايه مونږ ته کاميابى راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14907, 'Psalms 118:26', 'Psalms', 118, 26, '&nbsp;بختور دے هغه څوک چې د مالِک خُدائ په نوم راځى. د مالِک خُدائ د کور نه مونږ ستاسو برکت غواړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14908, 'Psalms 118:27', 'Psalms', 118, 27, '&nbsp;مالِک خُدائ، خُدائ پاک دے، هغۀ خپله رڼا په مونږ باندې وځلوله، قربانۍ راولئ او په پړو يې د قربان‌ګاه ښکرونو سره وتړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14909, 'Psalms 118:28', 'Psalms', 118, 28, '&nbsp;تۀ مې خُدائ پاک يې او زۀ به ستا شُکر ادا کړم، تۀ مې خُدائ پاک يې زۀ به ستا لوئى بيان کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14910, 'Psalms 118:29', 'Psalms', 118, 29, '&nbsp;د مالِک خُدائ شُکر ادا کړئ ځکه چې هغه ښۀ دے، د هغۀ مينه د تل دپاره پاتې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14911, 'Psalms 119:1', 'Psalms', 119, 1, '&nbsp;بختور دى هغوئ د چا کارونه چې بې‌داغه وى څوک چې د مالِک خُدائ د شريعت په مطابق چليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14912, 'Psalms 119:2', 'Psalms', 119, 2, '&nbsp;بختور دى هغوئ څوک چې د هغۀ قانون ساتى او په خپل ټول زړۀ سره د هغۀ لټون کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14913, 'Psalms 119:3', 'Psalms', 119, 3, '&nbsp;دوئ بې‌اِنصافه کارونه نۀ کوى، او دوئ د هغۀ په نقش قدم ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14914, 'Psalms 119:4', 'Psalms', 119, 4, '&nbsp;مونږ ته تا د خپلو اصُولو په حقله حُکم وکړو چې هغه په پوره توګه ومنو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14915, 'Psalms 119:5', 'Psalms', 119, 5, '&nbsp;کاش چې زما لارې پخې شى چې زۀ ستا شريعت د خپل ځان نه څرګند کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14916, 'Psalms 119:6', 'Psalms', 119, 6, '&nbsp;نو بيا به زۀ شرمنده نۀ شم ځکه چې زۀ ستا په ټولو حُکمونو باندې عمل کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14917, 'Psalms 119:7', 'Psalms', 119, 7, '&nbsp;زۀ به ستا په رښتينې زړۀ سره شُکر ادا کړم لکه څنګه چې زۀ ستا صادقه قانون زده کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14918, 'Psalms 119:8', 'Psalms', 119, 8, '&nbsp;زۀ به ستا اصُول منم، په پوره توګه ما رد نۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14919, 'Psalms 119:9', 'Psalms', 119, 9, '&nbsp;په ځوانۍ کښې به څنګه يو کس خپل عمل پاک وساتى؟ څوک چې ستا د کلام په مطابق اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14920, 'Psalms 119:10', 'Psalms', 119, 10, '&nbsp;زۀ په پوره زړۀ سره ستا لټون کوم، ما مۀ پرېږده چې ستا د حُکمونو نه بې‌لارې شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14921, 'Psalms 119:11', 'Psalms', 119, 11, '&nbsp;ستا کلام مې خپل زړۀ کښې ساتلے دے نو چې زۀ ستا خلاف ګناه ونۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14922, 'Psalms 119:12', 'Psalms', 119, 12, '&nbsp;ټول ثناء صِفتونه تا ته دى اے مالِکه خُدايه، ستا اصُول ما ته را زده کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14923, 'Psalms 119:13', 'Psalms', 119, 13, '&nbsp;زۀ په خپله خولۀ د هغوئ بيان کوم هغه ټول قوانين کوم چې ستا د خولې نه صادر شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14924, 'Psalms 119:14', 'Psalms', 119, 14, '&nbsp;زۀ ستا په اصُول منلو خوشحاله يم لکه څنګه چې يو سړے په ډېر مال دولت خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14925, 'Psalms 119:15', 'Psalms', 119, 15, '&nbsp;زۀ ستا په تعليماتو باندې غور کوم او ستا د لارو احترام کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14926, 'Psalms 119:16', 'Psalms', 119, 16, '&nbsp;زۀ ستا په اصُولو خوشحالېږم، او ستا کلام به زۀ نۀ هېروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14927, 'Psalms 119:17', 'Psalms', 119, 17, '&nbsp;خپل خِدمتګار سره ښۀ کوه نو زۀ به داسې ژوندے يم، او زۀ به ستا په کلام باندې عمل کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14928, 'Psalms 119:18', 'Psalms', 119, 18, '&nbsp;سترګې مې پرانيزه چې زۀ ووينم او ستا د قانون عجيبه حقائق وګورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14929, 'Psalms 119:19', 'Psalms', 119, 19, '&nbsp;زۀ په دې زمکه مسافر يم، ما نه خپل حُکمونه مۀ پټوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14930, 'Psalms 119:20', 'Psalms', 119, 20, '&nbsp;زما ځان په غوښتو غوښتو ستړے شوے دے هر وخت ستا د قانون غوښتو دپاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14931, 'Psalms 119:21', 'Psalms', 119, 21, '&nbsp;تۀ کبرژن او لعنتيان رټې او هغوئ څوک چې ستا د حُکمونو نه اوړېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14932, 'Psalms 119:22', 'Psalms', 119, 22, '&nbsp;ما نه د هغوئ کينه او سپکوالے لرې کړه، ځکه چې زۀ ستا قانون منم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14933, 'Psalms 119:23', 'Psalms', 119, 23, '&nbsp;تر دې چې بادشاهان رايوځائ کيږى او زما خلاف خبرې کوى، خو ستا خِدمتګار به ستا په قانون غور کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14934, 'Psalms 119:24', 'Psalms', 119, 24, '&nbsp;ستا اصُول زما خوشحالى ده، او زما دپاره ښۀ نصيحت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14935, 'Psalms 119:25', 'Psalms', 119, 25, '&nbsp;زۀ په خاورو کښې پروت يم، او په خپل کلام دې ما راژوندے کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14936, 'Psalms 119:26', 'Psalms', 119, 26, '&nbsp;ما خپلې لارې تا ته ښکاره کړې او تا جواب راکړو، ما ته خپل اصُول راوښايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14937, 'Psalms 119:27', 'Psalms', 119, 27, '&nbsp;ما د خپل کلام په تعليماتو باندې پوهه کړه، نو ستا په عجيبه کارونو به بيا غور وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14938, 'Psalms 119:28', 'Psalms', 119, 28, '&nbsp;د غمه زما ځان کمزورے شوے دے، په خپل کلام دې ما له طاقت راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14939, 'Psalms 119:29', 'Psalms', 119, 29, '&nbsp;ما د دروغژنو لارو نه وساته، او د خپل شريعت په ښودلو کښې دې په ما مهربانى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14940, 'Psalms 119:30', 'Psalms', 119, 30, '&nbsp;ما د رښتينوالۍ لاره خوښه کړې ده، او ستا شريعت مې په خپل زړۀ کښې ځائ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14941, 'Psalms 119:31', 'Psalms', 119, 31, '&nbsp;مالِکه خُدايه ستا اصُول مې راټينګ کړى دى، ما شرمېدو ته مۀ پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14942, 'Psalms 119:32', 'Psalms', 119, 32, '&nbsp;زۀ ستا د شريعت په لار روان يم، ځکه چې تا زما زړۀ لوئ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14943, 'Psalms 119:33', 'Psalms', 119, 33, '&nbsp;اے مالِکه خُدايه ما ته وښايه چې ستا په شريعت عمل وکړم، زۀ به تل په هغې باندې عمل کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14944, 'Psalms 119:34', 'Psalms', 119, 34, '&nbsp;نو ما ته ستا په شريعت باندې پوهه راکړه نو زۀ به بيا پرې عمل کوم او په خپل ټول زړۀ سره به پرې عمل کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14945, 'Psalms 119:35', 'Psalms', 119, 35, '&nbsp;ما د خپلو حُکمونو په لارو باندې روان کړه، او چې زۀ په کښې خپله خوشحالى پېدا کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14946, 'Psalms 119:36', 'Psalms', 119, 36, '&nbsp;زما زړۀ دې د خپل شريعت طرف ته راوګرځوه او د مال دولت لالچ طرف ته يې مۀ ګرځوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14947, 'Psalms 119:37', 'Psalms', 119, 37, '&nbsp;زما نظر د بې‌کاره څيزونو نه واړوه، او د خپل کلام په مطابق دې ژوند راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14948, 'Psalms 119:38', 'Psalms', 119, 38, '&nbsp;خپله وعده دې د خپل خِدمتګار سره پوره کړه، هغه وعده چې تا د هغه چا سره کړې وه څوک چې تا نه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14949, 'Psalms 119:39', 'Psalms', 119, 39, '&nbsp;د کومې بې‌عزتۍ نه چې يرېږم هغه زما نه اخوا کړه، ځکه چې ستا شريعت ښۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14950, 'Psalms 119:40', 'Psalms', 119, 40, '&nbsp;زۀ ستا د تعليماتو څومره خواهشمند يم، او په خپل صداقت کښې دې زما ژوند تازه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14951, 'Psalms 119:41', 'Psalms', 119, 41, '&nbsp;خپله ابدى مينه دې ما له راکړه اے مالِکه خُدايه، او د خپلې وعدې په مطابق دې خلاصون راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14952, 'Psalms 119:42', 'Psalms', 119, 42, '&nbsp;څوک چې ما ته پېغور راکوى نو بيا به زۀ جواب ورکړم، ځکه چې زۀ ستا په کلام باور کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14953, 'Psalms 119:43', 'Psalms', 119, 43, '&nbsp;زما د خولې نه د حقيقت کلام مۀ اخله، ځکه چې ما خپل اُميد ستا په شريعت باندې وتړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14954, 'Psalms 119:44', 'Psalms', 119, 44, '&nbsp;زۀ به هر وخت ستا د شريعت تابعدارى کوم، او د تل دپاره به يې منم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14955, 'Psalms 119:45', 'Psalms', 119, 45, '&nbsp;زۀ به په آزادۍ سره ګرځم، ځکه چې ما خپل ځان ستا حُکمونو ته وقف کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14956, 'Psalms 119:46', 'Psalms', 119, 46, '&nbsp;زۀ به ستا شريعت بادشاهانو ته بيان کړم زۀ به د چا نه هم نۀ شرمېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14957, 'Psalms 119:47', 'Psalms', 119, 47, '&nbsp;ستا په حُکمونو کښې زما خوشحالى ده ځکه چې زما ورسره مينه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14958, 'Psalms 119:48', 'Psalms', 119, 48, '&nbsp;ستا حُکمونه مې خوښيږى او عزت يې کوم، او زۀ ستا په اصُولو باندې سوچ کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14959, 'Psalms 119:49', 'Psalms', 119, 49, '&nbsp;خپل خِدمتګار ته دې خپله خبره راياده کړه، ځکه چې دا زما اُميد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14960, 'Psalms 119:50', 'Psalms', 119, 50, '&nbsp;زما په سختۍ کښې هم دا زما تسلى ده، چې هم ستا وعده به ما ژوندے ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14961, 'Psalms 119:51', 'Psalms', 119, 51, '&nbsp;کبرژن زما د حد نه زيات سپکاوے کوى، خو زۀ به ستا د شريعت نه وانۀ وړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14962, 'Psalms 119:52', 'Psalms', 119, 52, '&nbsp;اے مالِکه خُدايه ستا پخوانے شريعت ما ته ياد دے، او زما په دې باندې تسلى کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14963, 'Psalms 119:53', 'Psalms', 119, 53, '&nbsp;زۀ بدکارانو ته ډيرې غصې راخستے يم، هغوئ چا چې ستا شريعت پرېښے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14964, 'Psalms 119:54', 'Psalms', 119, 54, '&nbsp;ستا شريعت زما د سندرو مرکز دے په هر ځائ کښې چې زۀ اوسېدلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14965, 'Psalms 119:55', 'Psalms', 119, 55, '&nbsp;اے مالِکه خُدايه په شپه کښې زۀ ستا نوم يادوم، زۀ به ستا په شريعت باندې عمل کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14966, 'Psalms 119:56', 'Psalms', 119, 56, '&nbsp;دا زما چال چلن وو، چې ستا په قانون باندې عمل وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14967, 'Psalms 119:57', 'Psalms', 119, 57, '&nbsp;تۀ زما ميراث يې اے مالِکه خُدايه، ما دا وعده کړې ده چې ستا په شريعت به عمل کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14968, 'Psalms 119:58', 'Psalms', 119, 58, '&nbsp;ما ستا د رضا په خپل ټول زړۀ سره لټون کړے دے. د خپلې وعدې په مطابق په ما مهربانه اوسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14969, 'Psalms 119:59', 'Psalms', 119, 59, '&nbsp;ما په خپلو لارو غور کړے دے او ما خپل قدمونه ستا قانون ته راګرځولى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14970, 'Psalms 119:60', 'Psalms', 119, 60, '&nbsp;زۀ به زړۀ نا زړۀ او ځنډ نۀ کوم چې ستا حُکمونه ومنم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14971, 'Psalms 119:61', 'Psalms', 119, 61, '&nbsp;هر څو کۀ بدعمله مې په پړو تړل غواړى، خو زۀ به ستا شريعت نۀ هېروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14972, 'Psalms 119:62', 'Psalms', 119, 62, '&nbsp;په نيمه شپه راپاڅمه چې ستا شُکر ادا کړم ستا د صادقه شريعت دپاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14973, 'Psalms 119:63', 'Psalms', 119, 63, '&nbsp;هر څوک چې تا نه يريږى زۀ د هغوئ ټولو ملګرے يم، او د هغوئ ټولو هم څوک چې ستا په شريعت عمل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14974, 'Psalms 119:64', 'Psalms', 119, 64, '&nbsp;زمکه ستا د ابدى مينې نه ډکه ده اے مالِکه خُدايه، ما ته د خپل اصُول سبق راوښايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14975, 'Psalms 119:65', 'Psalms', 119, 65, '&nbsp;د خپل خِدمتګار سره دې ښۀ وکړل د خپل کلام په مطابق اے مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14976, 'Psalms 119:66', 'Psalms', 119, 66, '&nbsp;ما ته ښۀ عقل او پوهه راوښايه، ځکه چې زۀ ستا په حُکمونو باور کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14977, 'Psalms 119:67', 'Psalms', 119, 67, '&nbsp;د دې نه وړاندې چې تکليف راورسيږى، بې‌لارې شوے وم، خو اوس ستا په کلام عمل کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14978, 'Psalms 119:68', 'Psalms', 119, 68, '&nbsp;تۀ ښۀ يې او نېک کارونه کوې، ما ته دې خپل اصُول راوښايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14979, 'Psalms 119:69', 'Psalms', 119, 69, '&nbsp;کۀ څۀ هم چې مغرورانو په ما پورې دروغ تړلى دى، زۀ د خپل ټول زړۀ سره ستا اصُول ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14980, 'Psalms 119:70', 'Psalms', 119, 70, '&nbsp;د دوئ زړونه بې‌احساسه او بې‌رحمه دى، خو ستا په قانون کښې زۀ خوشحاله يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14981, 'Psalms 119:71', 'Psalms', 119, 71, '&nbsp;دا زما دپاره ښه وه چې په تکليف شوم نو دغه شان به زۀ ستا قانون زده کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14982, 'Psalms 119:72', 'Psalms', 119, 72, '&nbsp;ستا د خولې خبره زما دپاره ډېر اهميت لرى په زرګونو د سپينو او سرو زرو سيکو نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14983, 'Psalms 119:73', 'Psalms', 119, 73, '&nbsp;تا زۀ په خپلو لاسونو جوړ او تيار کړمه نو ما له پوهه راکړه چې ستا حُکمونه زده کړمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14984, 'Psalms 119:74', 'Psalms', 119, 74, '&nbsp;هغه څوک چې تا نه يريږى دوئ دې خوشحالى وکړى کله چې ما وګورى ځکه چې ما خپل اُميد ستا کلام پورې تړلے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14985, 'Psalms 119:75', 'Psalms', 119, 75, '&nbsp;زۀ په دې پوهېږمه اے مالِکه خُدايه چې ستا شريعت صادق دے او د خپلې وفادارۍ په وجه دې زۀ په تکليف کړے يمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14986, 'Psalms 119:76', 'Psalms', 119, 76, '&nbsp;ستا نۀ ختمېدونکې مينه دې ما له تسلى راکړى د هغه وعدې په مطابق کومه چې تا د خپل خِدمتګار سره کړې ده', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14987, 'Psalms 119:77', 'Psalms', 119, 77, '&nbsp;په ما رحم وکړه چې زۀ ژوندے پاتې شمه ځکه چې ستا شريعت ما خوشحالوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14988, 'Psalms 119:78', 'Psalms', 119, 78, '&nbsp;کبرژن دې په شرمونو وشرميږى برناحقه په ما دروغ وائى خو زۀ ستا په لارښودنو باندې غور او فکر کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14989, 'Psalms 119:79', 'Psalms', 119, 79, '&nbsp;ما ته دې راشى څوک چې تا نه يريږى هغوئ څوک چې ستا په شريعت پوهيږى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14990, 'Psalms 119:80', 'Psalms', 119, 80, '&nbsp;زما زړۀ دې ستا قانون منلو دپاره بې‌داغه وى نو داسې به زۀ ونۀ شرمېږمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14991, 'Psalms 119:81', 'Psalms', 119, 81, '&nbsp;ستا د خلاصون په انتظار زما ځان کمزورے کيږى خو ما خپل اُميد ستا کلام پورې تړلے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14992, 'Psalms 119:82', 'Psalms', 119, 82, '&nbsp;ستا د وعدې په انتظار مې سترګې ړندې شوې زۀ دا وايم چې، ”تۀ به ما له تسلى کله راکوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14993, 'Psalms 119:83', 'Psalms', 119, 83, '&nbsp;زۀ په لوګى کښې لکه د مشک په شان اوچ شوے يم. خو ستا اصُول نۀ هېرومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14994, 'Psalms 119:84', 'Psalms', 119, 84, '&nbsp;ترڅو به ستا خِدمتګار انتظار کوى څوک چې زما سره زياتے کوى تۀ به کله سزا ورکوې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14995, 'Psalms 119:85', 'Psalms', 119, 85, '&nbsp;زما دپاره مغروران کنده جوړوى ځکه چې ستا د قانون مخالفت کوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14996, 'Psalms 119:86', 'Psalms', 119, 86, '&nbsp;ستا ټول حُکمونه باورى دى زما مدد وکړه ځکه چې بې‌وجه ما خلق زوروى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14997, 'Psalms 119:87', 'Psalms', 119, 87, '&nbsp;زۀ خو دوئ تقريباً د زمکې نه ورک کړے يمه خو ستا اصُول ما پرېښودى نۀ دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14998, 'Psalms 119:88', 'Psalms', 119, 88, '&nbsp;د خپلې وفادارې مينې په مطابق دې زما ژوند وساته نو زۀ به ستا د خولې په تعليماتو عمل وکړمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14999, 'Psalms 119:89', 'Psalms', 119, 89, '&nbsp;اے مالِکه خُدايه ستا کلام ابدى دے او دا په آسمانونو کښې قائم دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15000, 'Psalms 119:90', 'Psalms', 119, 90, '&nbsp;ستا وفادارى به په ټولو نسلونو کښې وى تا زمکه پېدا کړه چې تر اوسه لا قائمه ده', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');